css:
.adaptive {
  position: relative;
  width: 190px;
  height: 64px;
  background: transparent;
  border: 0;
  cursor: pointer;
  color: #111;
  font-size: 18px;
  font-weight: 500;
}

.adaptive span {
  position: relative;
  z-index: 3;
}

.adaptive::before,
.adaptive::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 1px solid #111;
  transition:
    transform 0.8s cubic-bezier(0.16, 1, 0.3, 1),
    border-radius 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.adaptive::after {
  transform: translate(0, 0);
  opacity: 0.25;
}

.adaptive:hover::before {
  transform: translate(8px, -8px) rotate(-2deg);
  border-radius: 30px 5px 30px 5px;
}

.adaptive:hover::after {
  transform: translate(-8px, 8px) rotate(2deg);
  border-radius: 5px 30px 5px 30px;
}

.adaptive:hover span {
  animation: textShift 0.5s ease;
}

@keyframes textShift {
  0% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(5px);
  }
  100% {
    transform: translateX(0);
  }
}
